@import '../../utils/control-density.css';
@import '../../utils/control-parts.css';
@import '../../utils/chrome-layout.css';
@import '../../utils/forced-colors.css';

:host {
  position: absolute;
  z-index: var(--dimension-z-index-tooltip);
  background-color: var(--color-translucent-translucent);
  backdrop-filter: blur(var(--effect-blur-md));
  -webkit-backdrop-filter: blur(var(--effect-blur-md));
  border-radius: var(--dimension-radius-075);
  box-shadow: var(--effect-elevation-elevated-floating);
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
}

:host(.tooltip-chart--visible) {
  animation: tooltip-chart-fade-in var(--effect-motion-short-2) forwards;
}

.tooltip-chart__item {
  width: 100%;
  border-radius: var(--ds-control-radius, var(--dimension-radius-025));
}

.tooltip-chart__items {
  display: contents;
}

.tooltip-chart__swatch-box {
  pointer-events: none;
}

.tooltip-chart__swatch {
  width: var(--dimension-size-100);
  height: var(--dimension-size-100);
  flex: none;
  border-radius: var(--dimension-radius-half);
  background: var(--ds-tooltip-chart-swatch);
}

.tooltip-chart__value {
  margin-inline-start: auto;
  text-align: end;
}

.tooltip-chart__label,
.tooltip-chart__value {
  flex: none;
}

@keyframes tooltip-chart-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  :host(.tooltip-chart--visible) {
    animation: none;
    opacity: 1;
  }
}

@media (forced-colors: active) {
  :host {
    box-shadow: none;
    outline: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    outline-offset: calc(-1 * var(--dimension-stroke-width-012));
  }
}

import { Component, Prop, State, Element, Watch, h, Host } from '@stencil/core';
import {
  CONTROL_SUPPORTING_TEXT_VARIANT,
  CONTROL_TEXT_VARIANT,
  resolveCssTimeMs,
  TOKEN_DEFAULTS,
} from '../../utils';

const CURSOR_OFFSET_PX = 12;
const VIEWPORT_PAD_PX = 8;

export type TooltipChartSide = 'left' | 'right';
export type TooltipChartAlign = 'top' | 'bottom';

export interface TooltipChartItem {
  label: string;
  value: string | number;
  color?: string;
}

/**
 * Positioned value/label callout for chart hover interactions (bar, line point,
 * polar arc, …). A composition may suppress it when a visible legend already
 * surfaces the same value.
 * Unlike `ds-tooltip`, this doesn't bind to a slotted anchor element —
 * charts hover-highlight data that lives inside an SVG, so the chart itself computes
 * the anchor point (e.g. the cursor position while hovering) and passes it in as `x`/`y`.
 *
 * Renders `position: absolute` — place inside a `position: relative` chart wrapper,
 * with `x`/`y` as pixel coordinates within that wrapper. Defaults to sitting below-right
 * of the anchor (matching cursor-following tooltips), flipping to whichever side/edge
 * keeps it on-screen.
 *
 * Mount (or remount) when a hover session starts so `delay` applies once per hover;
 * keep the instance mounted while the cursor moves so tracking stays instant.
 */
@Component({
  tag: 'ds-tooltip-chart',
  styleUrl: 'TooltipChart.css',
  scoped: true,
})
export class TooltipChart {
  @Element() el!: HTMLElement;

  @Prop() value: string | number = '';
  @Prop() label: string = '';
  /** Optional heading for grouped chart focus. */
  @Prop() heading?: string;
  /** Multi-row content. When supplied, this replaces the legacy label/value row. */
  @Prop() items?: TooltipChartItem[];
  /** Anchor point in px, relative to the nearest `position: relative` ancestor — e.g. the cursor. */
  @Prop() x: number = 0;
  @Prop() y: number = 0;

  /**
   * Show delay after mount before the callout appears.
   * Default: `--effect-animation-delay-instant` (0ms). Accepts a number (ms)
   * or a TokoMo time token / `var(--effect-animation-delay-*)`. Charts need
   * immediate feedback while scrubbing; prefer the default. Mount once per
   * hover session so any non-zero delay runs once, then track `x`/`y` instantly.
   */
  @Prop() delay: number | string = TOKEN_DEFAULTS.animationDelayInstant;

  @State() private side: TooltipChartSide = 'right';
  @State() private align: TooltipChartAlign = 'bottom';
  @State() private visible: boolean = false;

  private delayTimer: ReturnType<typeof setTimeout> | null = null;

  componentDidLoad() {
    this.scheduleShow();
    this.calculatePlacement();
  }

  disconnectedCallback() {
    this.clearDelayTimer();
  }

  @Watch('x')
  @Watch('y')
  onAnchorChange() {
    requestAnimationFrame(() => this.calculatePlacement());
  }

  @Watch('delay')
  onDelayChange() {
    if (!this.visible) this.scheduleShow();
  }

  private get showDelayMs(): number {
    return resolveCssTimeMs(this.delay, TOKEN_DEFAULTS.animationDelayInstant);
  }

  private clearDelayTimer() {
    if (this.delayTimer) {
      clearTimeout(this.delayTimer);
      this.delayTimer = null;
    }
  }

  private scheduleShow() {
    this.clearDelayTimer();
    this.visible = false;
    const ms = this.showDelayMs;
    if (ms <= 0) {
      this.visible = true;
      return;
    }
    this.delayTimer = setTimeout(() => {
      this.delayTimer = null;
      this.visible = true;
      requestAnimationFrame(() => this.calculatePlacement());
    }, ms);
  }

  private calculatePlacement() {
    const rect = this.el.getBoundingClientRect();
    if (!rect.width || !rect.height) return;

    const nextSide: TooltipChartSide =
      rect.right > window.innerWidth - VIEWPORT_PAD_PX ? 'left' : 'right';
    const nextAlign: TooltipChartAlign =
      rect.bottom > window.innerHeight - VIEWPORT_PAD_PX ? 'top' : 'bottom';

    if (nextSide !== this.side) this.side = nextSide;
    if (nextAlign !== this.align) this.align = nextAlign;
  }

  render() {
    const translateX =
      this.side === 'right' ? `${CURSOR_OFFSET_PX}px` : `calc(-100% - ${CURSOR_OFFSET_PX}px)`;
    const translateY =
      this.align === 'bottom' ? `${CURSOR_OFFSET_PX}px` : `calc(-100% - ${CURSOR_OFFSET_PX}px)`;
    const rows = this.items ?? [{ label: this.label, value: this.value }];
    const usesSwatches = rows.some(item => Boolean(item.color));

    return (
      <Host
        class={{
          'tooltip-chart': true,
          'tooltip-chart--visible': this.visible,
          'ds-chrome-column': true,
          'ds-chrome-space--sm': true,
        }}
        style={{
          left: `${this.x}px`,
          top: `${this.y}px`,
          transform: `translate(${translateX}, ${translateY})`,
        }}
      >
        {this.heading && (
          <ds-text
            class="tooltip-chart__heading ds-control-section-heading ds-control--md"
            as="span"
            variant={CONTROL_SUPPORTING_TEXT_VARIANT.md}
            emphasis
            color="var(--color-foreground-primary)"
          >
            {this.heading}
          </ds-text>
        )}
        <div class="tooltip-chart__items">
          {rows.map((item, index) => (
            <div
              class="tooltip-chart__item ds-control-frame ds-control--md"
              key={`${item.label}-${index}`}
            >
              {usesSwatches && (
                <span class="tooltip-chart__swatch-box ds-control-icon-box" aria-hidden="true">
                  {item.color && (
                    <span
                      class="tooltip-chart__swatch"
                      style={{ '--ds-tooltip-chart-swatch': item.color }}
                    />
                  )}
                </span>
              )}
              <ds-text
                class="tooltip-chart__label ds-control-label-box"
                as="span"
                variant={CONTROL_TEXT_VARIANT.md}
                color="var(--color-foreground-secondary)"
              >
                {item.label}
              </ds-text>
              <ds-text
                class="tooltip-chart__value ds-control-label-box"
                as="span"
                variant={CONTROL_TEXT_VARIANT.md}
                emphasis
                color="var(--color-foreground-primary)"
              >
                {item.value}
              </ds-text>
            </div>
          ))}
        </div>
      </Host>
    );
  }
}
